FUNCTION_BLOCK FB_S06
VAR_INPUT
    TempPV : REAL;
    SetTemp : REAL;
    Segment : INT;
    LoadReduceReq : BOOL;
END_VAR
VAR_OUTPUT
    HeatOn : BOOL := FALSE;
    FanOn : BOOL := FALSE;
    OverTempAlarm : BOOL := FALSE;
    LoadReduce : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    StartupScans : INT := 0;
    TargetTemp : REAL := 0.0;
    InvalidSegment : BOOL := FALSE;
    PreviousInvalidSegment : BOOL := FALSE;
    ThermalReduce : BOOL := FALSE;
    HeatDemand : BOOL := FALSE;
    FanWasOn : BOOL := FALSE;
END_VAR

(*
    每次调用为一个 20 ms 扫描周期。

    待审语义冲突，不能视为已解决：
    1. 原文要求超温先降载而不是直接断电；C1/C4 要求降载与加热互斥。
       本实现暂按保护优先，同一扫描置降载并关闭 HeatOn。
       接口没有负载功率档位，无法表达保持加热的实际降功率过程。
    2. 原文降载撤销门限为分段目标温度 -3，且严格低于；
       C7 报警保持门限使用 SetTemp -3，且允许等于。
       分别实现降载迟滞和报警保持，不混同两个门限。
    3. 原文要求非法段当前报错；C8 要求下一周期报错。
       当前非法或上一周期非法均报 8601，因此恢复合法后多保持一扫描。
       非法段错误优先于超温降载状态。
    4. 初态描述首周期关断；C10 的闭区间 [0,1] 覆盖两个周期。
       本实现前两次调用关断全部 BOOL 输出，此时不执行温控。
       与启动期间立即执行超温保护存在冲突，仍待审。

    风机预启动至少一个扫描；没有风机反馈，不能验证实际风机运行。
    本源码未声明已经通过编译或逐周期功能验证。
*)

InvalidSegment := (Segment < 0) OR (Segment > 2);

CASE Segment OF
    0:
        TargetTemp := SetTemp * REAL#0.5;
    1:
        TargetTemp := SetTemp * REAL#0.8;
    2:
        TargetTemp := SetTemp;
ELSE
    TargetTemp := SetTemp * REAL#0.5;
END_CASE;

IF StartupScans < 2 THEN
    StartupScans := StartupScans + 1;

    HeatOn := FALSE;
    FanOn := FALSE;
    OverTempAlarm := FALSE;
    LoadReduce := FALSE;
    ThermalReduce := FALSE;
    HeatDemand := FALSE;
ELSE
    FanWasOn := FanOn;

    (* 超温置位优先；降载严格低于分段目标 -3 才复位。 *)
    IF TempPV > (TargetTemp + REAL#10.0) THEN
        ThermalReduce := TRUE;
    ELSIF TempPV < (TargetTemp - REAL#3.0) THEN
        ThermalReduce := FALSE;
    END_IF;

    (* 报警独立保持，采用 C7 指定的 SetTemp 复位门限。 *)
    IF TempPV > (TargetTemp + REAL#10.0) THEN
        OverTempAlarm := TRUE;
    ELSIF TempPV <= (SetTemp - REAL#3.0) THEN
        OverTempAlarm := FALSE;
    END_IF;

    (* 上位请求按电平执行，不撤销尚未复位的超温降载。 *)
    LoadReduce := ThermalReduce OR LoadReduceReq;

    (* 温控死区：边界相等时保持；保护覆盖温控需求。 *)
    IF TempPV < (TargetTemp - REAL#5.0) THEN
        HeatDemand := TRUE;
    ELSIF TempPV > (TargetTemp + REAL#5.0) THEN
        HeatDemand := FALSE;
    END_IF;

    IF LoadReduce THEN
        HeatDemand := FALSE;
    END_IF;

    (* 降载期间保留通风；正常加热需上一扫描已打开风机。 *)
    FanOn := HeatDemand OR LoadReduce;
    HeatOn := HeatDemand AND FanWasOn AND FanOn AND NOT LoadReduce;
END_IF;

IF InvalidSegment OR PreviousInvalidSegment THEN
    Status := WORD#16#8601;
ELSIF ThermalReduce THEN
    Status := WORD#16#8602;
ELSE
    Status := WORD#16#0000;
END_IF;

PreviousInvalidSegment := InvalidSegment;

END_FUNCTION_BLOCK
